import React from 'react';
import './HomePage.css';
import UpMenu from './UpMenu/UpMenu';
import LeftMenu from './LeftMenu/LeftMenu';
import UserStatus from './TheFeed/UserStatus';
import RightMenu from './RightMenu/RightMenu';
import Posts from './TheFeed/Posts';
import posts from "./data/db.json";
import { useState } from 'react';
import { createContext } from 'react';

export const ThemeContext = createContext(null);



function HomePage({ activeUser }) {
    const [postsList, setPostsList] = useState(posts);
    const [theme, setTheme] = useState("light");

    
    const changeTheme = () => {
        setTheme((curr) => { return curr === "light" ? "dark" : "light"; });
    };

    const onEdit = (editedPost) => {
        const postIndex = postsList.findIndex(post => post.id === editedPost.id);
        postsList[postIndex].text = editedPost.text;
        postsList[postIndex].photo = editedPost.photo;
        setPostsList([...postsList]);
    }



    const updateCommentsCount = (id) => {
        const postIndex = postsList.findIndex(post => post.id === id);
        postsList[postIndex].comments++;
        setPostsList([...postsList]);
    }

    const likePost = (id, numLikes) => {
        const postIndex = postsList.findIndex(post => post.id === id);
        postsList[postIndex].like += numLikes;
        setPostsList([...postsList]);
    }

    const deletePost = (id) => {
        const postIndex = postsList.findIndex(post => post.id === id);
        if(postsList[postIndex].name === activeUser.displayName){
        postsList.splice(postIndex, 1);
        setPostsList([...postsList]);
        }
    }

    const updateDeleteCommentsCount = (id) => {
        const postIndex = postsList.findIndex(post => post.id === id);
        postsList[postIndex].comments--;
        setPostsList([...postsList]);
    }

    return (
        <ThemeContext.Provider value={{theme, changeTheme}}>
        <div className="container- fluid" id={theme}>
            <div className="row upfeed">

                <UpMenu activeUser={activeUser} changeTheme = {changeTheme}/>
            </div>
            <div className="row feed">
                <div className="col-3">
                    <LeftMenu activeUser={activeUser} />

                </div>
                <div className="row col-6">
                    <UserStatus
                        activeUser={activeUser}
                        setPostsList={setPostsList}
                        postsList={postsList} />
                        {postsList.map((post) =>
                        <Posts {...post}
                            activeUser={activeUser}
                            updateDeleteCommentsCount={updateDeleteCommentsCount}
                            onEdit={onEdit}
                            onLike={(likeCount) => likePost(post.id, likeCount)}
                            onDelete={() => deletePost(post.id)}
                            addComment={() => updateCommentsCount(post.id)}
                            key={post.id} />
                    )}

                </div>
                <div className="col-3">
                    <RightMenu />
                </div>
            </div>
        </div>
        </ThemeContext.Provider>
    );
}

export default HomePage;
